const BARBEROS = ['Joniel', 'Rubén', 'Styven', 'Sergio'];
const APERTURA = 9 * 60, CIERRE = 19 * 60;

const t = $('When Executed by Another Workflow').first().json;
const fecha = t.fecha_consulta;
const dur = Number(t.duracion_min);
const [hh, mm] = String(t.hora_inicio).split(':').map(Number);
const ini = hh * 60 + mm, fin = ini + dur;
const preferido = String(t.barbero_preferido || '').trim();

const dow = new Date(`${fecha}T12:00:00-05:00`).getUTCDay(); // 0 = domingo
if (dow === 0) {
  return [{ json: { disponible: false, motivo: 'Domingo: la barbería está cerrada', alternativas: [] } }];
}
if (ini < APERTURA || fin > CIERRE) {
  return [{ json: { disponible: false, motivo: 'Fuera del horario de atención (lunes a sábado, 9:00 a.m. a 7:00 p.m.)', alternativas: [] } }];
}

// Minutos del día en hora de Colombia (UTC-5)
const aMin = iso => {
  const d = new Date(new Date(iso).getTime() - 5 * 3600000);
  return d.getUTCHours() * 60 + d.getUTCMinutes();
};

const ocupados = Object.fromEntries(BARBEROS.map(b => [b, []]));
const sinAsignar = [];
for (const item of $input.all()) {
  const e = item.json;
  if (!e.start || !e.start.dateTime) continue;
  const iv = [aMin(e.start.dateTime), aMin(e.end.dateTime)];
  const m = String(e.summary || '').match(/\(([^)]+)\)\s*$/);
  const b = m ? m[1].trim() : null;
  if (b && ocupados[b]) ocupados[b].push(iv); else sinAsignar.push(iv);
}

const solapa = (iv, a, b) => iv[0] < b && iv[1] > a;
const libres = (a, b) => {
  const l = BARBEROS.filter(x => !ocupados[x].some(iv => solapa(iv, a, b)));
  const n = sinAsignar.filter(iv => solapa(iv, a, b)).length;
  return l.slice(0, Math.max(0, l.length - n));
};
const hora = m => `${String(Math.floor(m / 60)).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`;

const libresAhora = libres(ini, fin);
const elegido = preferido
  ? libresAhora.find(x => x.toLowerCase() === preferido.toLowerCase())
  : libresAhora[0];

if (elegido) {
  return [{ json: { disponible: true, barbero_asignado: elegido, barberos_libres: libresAhora, hora_inicio: hora(ini), hora_fin: hora(fin), alternativas: [] } }];
}

const alternativas = [];
for (let s = APERTURA; s + dur <= CIERRE; s += 30) {
  const l = libres(s, s + dur);
  const ok = preferido ? l.some(x => x.toLowerCase() === preferido.toLowerCase()) : l.length > 0;
  if (ok) alternativas.push({ hora: hora(s), diff: Math.abs(s - ini) });
}
alternativas.sort((a, b) => a.diff - b.diff);

return [{ json: {
  disponible: false,
  motivo: preferido && libresAhora.length ? `${preferido} no está disponible a esa hora` : 'No hay barberos libres a esa hora',
  alternativas: alternativas.slice(0, 3).map(a => a.hora)
} }];
